# ---------- V1.3.3 tests ----------
Path('test_v133.py').write_text(r'''import tempfile\nimport time\nimport unittest\nfrom dataclasses import replace\nfrom engine import Engine, Settings, Halt, make_plan\nimport test_engine\n\nclass V133ExecutionTests(unittest.TestCase):\n    def test_fixed_costs_and_reward(self):\n        s=Settings().validate()\n        self.assertEqual((s.fee_bps,s.taker_fee_bps,s.slippage_bps,s.reward_r),(2.0,5.0,5.0,2.0))\n        for changed in (dict(fee_bps=3),dict(taker_fee_bps=4),dict(slippage_bps=4),dict(reward_r=1.5)):\n            with self.assertRaises(Halt): replace(s,**changed).validate()\n\n    def test_plan_is_half_at_1r_half_at_2r(self):\n        p=make_plan(Settings(), '做多', test_engine.TICK, test_engine.META, 200, 100, 3)\n        entry=float(p['px']); risk=entry-float(p['sl'])\n        self.assertAlmostEqual(float(p['tp1'])-entry,risk,delta=.2)\n        self.assertAlmostEqual(float(p['tp2'])-entry,2*risk,delta=.2)\n        self.assertAlmostEqual(float(p['tp1_sz'])+float(p['tp2_sz']),float(p['sz']))\n        self.assertTrue(p['breakeven_after_tp1'])\n\n    def _engine(self):\n        folder=tempfile.TemporaryDirectory(); x=test_engine.FakeExchange(); e=Engine(x,folder.name); e.connect(); e.arm(Settings())\n        e.market={'side':'做多','bar':int(time.time()//300)*300000-300000,'close':60000,'h':{'atr':2000},'m':{'atr':200},'scores':{'做多':{'gate':True,'total':8,'level':'普通信号','items':[]}}}\n        e.market_at=time.time(); e.market_monotonic=time.monotonic(); e.cycle(); return folder,x,e,e.store.data['active']\n\n    def test_order_has_two_split_tp_and_cost_price_sl(self):\n        folder,x,e,p=self._engine()\n        try:\n            body=[b for path,b in x.writes if path.endswith('/order')][-1]\n            tps=[a for a in body['attachAlgoOrds'] if a.get('tpTriggerPx')]\n            sl=[a for a in body['attachAlgoOrds'] if a.get('slTriggerPx')]\n            self.assertEqual(len(tps),2); self.assertEqual(len(sl),1)\n            self.assertEqual(sl[0]['amendPxOnTriggerType'],'1')\n            self.assertAlmostEqual(sum(float(a['sz']) for a in tps),float(body['sz']))\n            self.assertNotEqual(tps[0]['tpTriggerPx'],tps[1]['tpTriggerPx'])\n            self.assertNotEqual(tps[0]['tpOrdPx'],tps[1]['tpOrdPx'])\n        finally: folder.cleanup()\n\n    def test_tp1_requires_breakeven_sl_verification(self):\n        folder,x,e,p=self._engine()\n        try:\n            x.ord={'state':'filled','accFillSz':p['sz']}\n            x.pos=[dict(mgnMode='isolated',posSide=p['posSide'],pos=p['tp2_sz'],avgPx=p['px'])]\n            opposite='sell'\n            x.protections=[\n                dict(algoClOrdId=p['tp2_id'],state='live',posSide=p['posSide'],side=opposite,tdMode='isolated',tpTriggerPx=p['tp2'],sz=p['tp2_sz']),\n                dict(algoClOrdId=p['sl_id'],state='live',posSide=p['posSide'],side=opposite,tdMode='isolated',slTriggerPx=p['px'],slOrdPx='-1',amendPxOnTriggerType='1')]\n            e.cycle()\n            self.assertTrue(e.store.data['active']['tp1_done']); self.assertTrue(e.store.data['active']['breakeven_verified'])\n        finally: folder.cleanup()\n\nif __name__=='__main__': unittest.main(verbosity=2)\n''')

Path('RELEASE-1.3.3.md').write_text('''# KAYTRADE 1.3.3\n\n- 交易总览整体可滚动，小窗口与Mac触控板可继续下滑。\n- 卡片、页签与输入控件统一圆角；信息卡增加克制的深色玻璃层次。\n- 放大BTC价格与做多/做空核心信息，辅助提示缩小压暗。\n- 风险设置与执行参数拆分；交易计划移入交易总览。\n- 固定执行成本：OKX Maker 0.02%、Taker 0.05%、滑点预算0.05%，界面不开放修改。\n- SL继续按15m ATR。TP1=1R平50%，TP2=2R平剩余50%。\n- 使用OKX Split TP + Cost-price SL：首个TP触发后由交易所把剩余SL自动移动到成交均价，并由程序核对。\n- V1.3.2的10分评分策略与安全停机原则保持不变。\n''')

Path('.github/workflows/build-mac-v133.yml').write_text('''name: Build KAYTRADE Intel Mac 1.3.3\non:\n  push:\n    branches: [codex/v1-3-3-ui-execution]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  build:\n    runs-on: macos-15-intel\n    timeout-minutes: 30\n    env:\n      MACOSX_DEPLOYMENT_TARGET: '14.0'\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: '3.13'\n          architecture: x64\n      - name: Install packaging dependencies\n        run: python -m pip install 'pyinstaller==6.16.0' 'certifi==2025.8.3' 'Pillow==11.3.0'\n      - name: Test V1.3.3 and preserved safety\n        run: |\n          python -m py_compile strategy.py engine.py exchange.py candles.py app.py visual.py desktop.py\n          python -m unittest -v test_engine test_candles test_v122 test_v132 test_v133\n      - name: Verify V1.3.3 wiring\n        run: |\n          python - <<'PY'\n          from pathlib import Path\n          e=Path('engine.py').read_text(); a=Path('app.py').read_text(); v=Path('visual.py').read_text()\n          for token in ("reward_r:float=2.0","taker_fee_bps:float=5.0","amendPxOnTriggerType':'1'","tp1_sz","tp2_sz"):\n              assert token in e, token\n          for token in ('KAYTRADE 1.3.3','风险设置','执行参数','交易计划','TP1 · 50%','TP2 · 余下50%'):\n              assert token in a, token\n          assert 'class ScrollablePage' in v and 'class MetricTile' in v\n          print('V1.3.3 wiring OK')\n          PY\n      - name: Create application icon\n        run: python build_icon.py\n      - name: Build Intel application\n        run: python -m PyInstaller --noconfirm OKXLocal.spec\n      - name: Verify bundle\n        run: python verify_bundle.py\n      - name: Packaged UI smoke test\n        run: |\n          dist/KAYTRADE.app/Contents/MacOS/KAYTRADE --smoke-test "$RUNNER_TEMP/kaytrade-smoke.txt"\n          test -s "$RUNNER_TEMP/kaytrade-smoke.txt"\n          cat "$RUNNER_TEMP/kaytrade-smoke.txt"\n          codesign --verify --deep --strict dist/KAYTRADE.app\n          cp "$RUNNER_TEMP"/ui-*.png . || true\n      - name: Create installer\n        run: |\n          mkdir -p installer\n          ditto dist/KAYTRADE.app installer/KAYTRADE.app\n          cp RELEASE-1.3.3.md installer/RELEASE-1.3.3.md\n          cp "$RUNNER_TEMP/kaytrade-smoke.txt" installer/BUILD-TEST.txt\n          ln -s /Applications installer/Applications\n          hdiutil create -volname KAYTRADE-1.3.3 -srcfolder installer -ov -format UDZO KAYTRADE-1.3.3-Intel-test.dmg\n          shasum -a 256 KAYTRADE-1.3.3-Intel-test.dmg > SHA256.txt\n      - uses: actions/upload-artifact@v4\n        with:\n          name: KAYTRADE-1.3.3-Intel-test\n          path: |\n            KAYTRADE-1.3.3-Intel-test.dmg\n            SHA256.txt\n            ui-*.png\n          if-no-files-found: error\n          retention-days: 14\n''')

